        Result groupedOwner=round.checks.values().stream().filter(r->r.proofs.stream().anyMatch(p->p.grouped!=null)).findFirst().get();Proof grouped=groupedOwner.proofs.stream().filter(p->p.grouped!=null).findFirst().get();java.lang.reflect.Field grade=grouped.getClass().getDeclaredField("support");grade.setAccessible(true);Support saved=grouped.support;grade.set(grouped,new Support(saved.sources,saved.depth+1));
        try{SessionCollection bad=ContextUniversalCompoundExchange.collectWithValidationReuse(f.x,round.input,cuts,round.checks,512,256,16,WORK,4096);no(bad.collection,"forged grouped grade after successful invocation");require(bad.metrics.entries==0,"failed memo released");}finally{grade.set(grouped,saved);}
