        Snapshot anchor=bind(true,"!anchor(1);"),foreign=bind(false,P+RULE),opinion=bind(false,"!b(1); !~r(1);");Packet ap=ContextPrivateWitnessPoolRunner.common(anchor);Exchange independent=yes(collect(anchor,ap,cuts(anchor,Arrays.asList(foreign,opinion),ap,Collections.emptyMap(),null),16));require(independent.clauses.isEmpty()&&ContextUniversalCompoundExchange.sameContents(null,independent,WORK),"foreign-only residuals cannot be communalized by unrelated X anchor");
